GLOSSARY = [
 {"term":"category theory","plain":"A branch of mathematics about things and the rules that carry one thing into another, used here as a bookkeeping language for design steps."},
 {"term":"morphism","plain":"One of those carrying rules, such as 'average these fibres into one layer'."},
 {"term":"simulation condition","plain":"The test that a carrying rule respects time: running then summarising equals summarising then running."},
 {"term":"bilayer","plain":"A strip made of two glued layers that bends when one layer swells or expands more than the other."},
 {"term":"hygromorph","plain":"A material that changes shape when the humidity changes, like a pine cone scale."},
 {"term":"Timoshenko formula","plain":"A century-old formula that tells how much a two-layer strip bends for a given mismatch in swelling."},
 {"term":"Lean / machine-checked","plain":"A proof written for a computer program (Lean) that checks every logical step, so a mistake cannot slip through."},
 {"term":"ceiling of 3/2","plain":"A proven upper limit: however you choose the layer thicknesses and stiffnesses, the strip cannot bend more than 1.5 times the mismatch divided by its thickness."},
 {"term":"fused filament fabrication (FFF)","plain":"Ordinary desktop 3D printing that melts a plastic thread and lays it down line by line."},
 {"term":"relaxation time","plain":"How long a material takes to settle after its surroundings change."},
 {"term":"G-code","plain":"The list of movement instructions a 3D printer follows."},
]

